const icon = (name, cls='') => `<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.sparkles}</svg>`;
function icons(root=document) { $$('svg[data-icon]',root).forEach(el => {el.setAttribute('viewBox','0 0 24 24');el.setAttribute('aria-hidden','true');el.innerHTML=paths[el.dataset.icon] || paths.sparkles;}); }
async function api(url, options={}) {
  const config = {...options, credentials:'same-origin', headers:{...(options.body && !(options.body instanceof FormData) ? {'Content-Type':'application/json'} : {}), ...options.headers}};
  if (config.body && !(config.body instanceof FormData) && typeof config.body !== 'string') config.body=JSON.stringify(config.body);
  const res=await fetch('/api'+url,config);
  const data=await res.json().catch(()=>({detail:'Không thể kết nối máy chủ.'}));
  if (!res.ok) {
    const message=Array.isArray(data.detail)?data.detail.map(x=>`${x.loc?.at(-1)||''}: ${x.msg}`).join(' · '):data.detail;
    const err=new Error(message||'Có lỗi xảy ra. Vui lòng thử lại.');err.status=res.status;throw err;
  }
  return data;
}
function toast(message,error=false) {
  const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=icon(error?'close':'check')+`<span>${esc(message)}</span>`;
  $('#toast-root').append(el);setTimeout(()=>el.remove(),4200);
}
async function syncUser() {
  state.user=await api('/auth/me');
  if(state.user){const [f,c]=await Promise.all([api('/favorites'),api('/cart')]);state.favorites=new Set(f.map(p=>p.id));state.cart=c;}
  else{state.favorites=new Set();state.cart={items:[],count:0,total:0,shipping:0};}
  badges();
}
function badges() {$('#cart-count').textContent=state.cart.count;$('#favorite-count').style.display=state.favorites.size?'block':'none';$$('[data-favorite]').forEach(el=>{const saved=state.favorites.has(+el.dataset.favorite);el.classList.toggle('saved',saved);el.setAttribute('aria-pressed',String(saved));el.setAttribute('aria-label',saved?'Bỏ yêu thích':'Yêu thích sản phẩm');});}
function requireLogin() {if(state.user)return true;toast('Đăng nhập để lưu phong cách và tiếp tục mua sắm.');sessionStorage.setItem('vela_return',location.pathname+location.search);go('/tai-khoan');return false;}
function go(url,{replace=false,scroll=true}={}) {closeModal();(replace?history.replaceState:history.pushState).call(history,{},'',url);$('#search-panel').hidden=true;$('#mobile-nav').hidden=true;render();if(scroll)window.scrollTo(0,0);}
function breadcrumb(label,previous='') {return `<div class="breadcrumb"><a href="/" data-link>Trang chủ</a><span>/</span>${previous?`<a href="/san-pham" data-link>Sản phẩm</a><span>/</span>`:''}<span>${esc(label)}</span></div>`;}
function empty(title,description,button='Khám phá thiết kế',href='/san-pham',name='bag') {return `<div class="empty-state">${icon(name)}<h2>${esc(title)}</h2><p>${esc(description)}</p>${button?`<a class="button primary" href="${href}" data-link>${esc(button)} ${icon('arrow')}</a>`:''}</div>`;}
function skeletons(n=6) {return `<div class="product-grid">${Array.from({length:n},()=>'<div><div class="skeleton skeleton-photo"></div><div class="skeleton skeleton-line"></div><div class="skeleton skeleton-line short"></div></div>').join('')}</div>`;}
const colorHex={'Đỏ rượu':'#823944','Đỏ':'#b5493d','Trắng':'#eeede6','Xanh':'#71828f','Kem':'#e2d9ba','Vàng':'#d8b747','Be':'#c7b8a0','Đen':'#353633','Nâu':'#a67655','Hồng':'#d8a7af','Bạc':'#b5b8ba','Xám than':'#505252','Xanh dương':'#668aa9','Xám':'#a0a4a3','Vàng ánh kim':'#c1a361','Tím':'#9581ae','Xanh navy':'#333d60','Hồng tím':'#b577a1','Xanh lá':'#82966d','Đồng':'#b3825c','Xám thép':'#78858a','Khaki':'#a4a07c','Đa sắc':'#bd9b8c','Cam':'#cc8a54'};
function productCard(p,{reason=false,score=false,index=0}={}) {
  const saved=state.favorites.has(p.id);
  return `<article class="product-card"><div class="product-photo ${p.thumbnail.includes('/catalog-')?'catalog-product-photo':''}"><a href="/san-pham/${p.id}" data-link aria-label="Xem ${esc(p.name)}" style="display:block;height:100%"><img src="${esc(p.thumbnail)}" alt="${esc(p.name)}" loading="${index<3?'eager':'lazy'}" width="600" height="800"></a>${p.original_price?`<span class="product-badge sale">−${Math.round((1-p.price/p.original_price)*100)}%</span>`:p.is_new?'<span class="product-badge">MỚI VỀ</span>':''}<button class="product-heart ${saved?'saved':''}" data-favorite="${p.id}" aria-label="${saved?'Bỏ yêu thích':'Yêu thích sản phẩm'}" aria-pressed="${saved}">${icon('heart')}</button><button class="quick-view" data-quick="${p.id}">${icon('eye')} Xem nhanh thiết kế</button>${score&&p.score!==undefined?`<span class="image-search-score">Tương đồng cosine: ${p.score.toFixed(3)}</span>`:''}</div><div class="product-info"><span class="product-category">${esc(p.brand)} / ${esc(p.category)}</span><a class="product-name" href="/san-pham/${p.id}" data-link>${esc(p.name)}</a><button class="product-cart" data-quick="${p.id}" aria-label="Chọn kích thước và thêm ${esc(p.name)} vào giỏ">${icon('bag')}</button><div class="product-price">${money(p.price)}${p.original_price?`<span class="old-price">${money(p.original_price)}</span>`:''}</div><div class="swatches"><span class="swatch" style="background:${colorHex[p.color]||'#b5ad98'}" title="${esc(p.color)}"></span><span style="font-size:7px;color:#97998a;margin-left:3px">${esc(p.color)}</span></div>${reason&&p.reason?`<p class="product-reason">✧ ${esc(p.reason)}</p>`:''}</div></article>`;
}
const grid=(items,options={})=>`<div class="product-grid ${options.catalog?'catalog-grid':''}">${items.map((p,index)=>productCard(p,{...options,index})).join('')}</div>`;
async function homePage() {
  const query=state.homeTab==='Tất cả'?'':`&gender=${encodeURIComponent(state.homeTab)}`;
  const catalog=state.user?await api('/recommendations/hybrid?k=6'+query):await api('/products?limit=6'+query);
  return homeExperience(catalog);
}
function checked(value,current){return value===current?'checked':'';}
async function catalogPage() {
  const params=new URLSearchParams(location.search);const apiParams=new URLSearchParams(params);apiParams.set('limit','12');
  const data=await api('/products?'+apiParams);
  const gender=params.get('gender')||'';const title=params.get('q')?`Kết quả cho “${params.get('q')}”`:gender==='Nữ'?'Nét riêng của nàng':gender==='Nam'?'Phong thái của chàng':gender==='Unisex'?'Phong cách không giới hạn':gender==='Phụ kiện'?'Chi tiết làm nên khác biệt':params.get('sort')==='newest'?'Một mùa cảm hứng mới':'Khám phá mọi thiết kế';
  return `<section class="container page-space">${breadcrumb('Bộ sưu tập')}<div class="page-intro"><span class="small-label">BỘ SƯU TẬP VELASTYLE</span><h1>${esc(title)}</h1><p>Những thiết kế được tuyển chọn để đồng hành cùng bạn, từ ngày thường đến những dịp đặc biệt.</p></div><div class="catalog-layout"><aside class="filter-sidebar" id="filter-sidebar"><form id="filter-form"><div class="filter-group"><h3>Phong cách dành cho <span>−</span></h3>${['Tất cả','Nữ','Nam','Unisex','Phụ kiện'].map(v=>`<label class="filter-option"><input type="radio" name="gender" value="${v==='Tất cả'?'':v}" ${checked(v==='Tất cả'?'':v,gender)}>${v}</label>`).join('')}</div><div class="filter-group"><h3>Danh mục <span>−</span></h3><select name="category" aria-label="Danh mục"><option value="">Tất cả danh mục</option>${state.categories.map(c=>`<option value="${c.id}" ${params.get('category')===String(c.id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="filter-group"><h3>Khoảng giá <span>−</span></h3>${[['','Tất cả mức giá'],['700000','Dưới 700.000đ'],['1000000','Dưới 1.000.000đ'],['1500000','Dưới 1.500.000đ'],['2500000','Dưới 2.500.000đ']].map(([v,l])=>`<label class="filter-option"><input type="radio" name="max_price" value="${v}" ${checked(v,params.get('max_price')||'')}>${l}</label>`).join('')}</div><div class="filter-group"><h3>Màu sắc <span>−</span></h3><div class="filter-color-list">${Object.entries(colorHex).map(([name,hex])=>`<button type="button" class="color-button ${params.get('color')===name?'active':''}" style="background:${hex}" data-filter-color="${name}" title="${name}" aria-label="Màu ${name}" aria-pressed="${params.get('color')===name}"></button>`).join('')}</div></div><div class="filter-group"><h3>Kích thước <span>−</span></h3><select name="size" aria-label="Kích thước"><option value="">Tất cả kích thước</option>${['S','M','L','XL','Freesize','35','36','37','38','39'].map(v=>`<option ${params.get('size')===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="filter-group"><h3>Thương hiệu <span>−</span></h3><select name="brand" aria-label="Thương hiệu"><option value="">Tất cả thương hiệu</option>${state.brands.map(b=>`<option value="${b.id}" ${params.get('brand')===String(b.id)?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><button type="button" class="filter-clear" data-action="clear-filters">Xóa tất cả bộ lọc</button></form></aside><div><form class="catalog-search" id="catalog-search">${icon('search')}<input name="q" placeholder="Tìm thiết kế bạn yêu…" value="${esc(params.get('q')||'')}" aria-label="Tìm trong bộ sưu tập"><button class="icon-btn" type="submit" aria-label="Tìm kiếm">${icon('arrow')}</button></form><div class="catalog-toolbar"><p>${data.total} thiết kế ${params.size?'phù hợp':'trong bộ sưu tập'}</p><button class="filter-mobile-toggle" data-action="toggle-filters">${icon('filter')} Bộ lọc</button><select id="catalog-sort" aria-label="Sắp xếp">${[['featured','Tuyển chọn nổi bật'],['newest','Mới nhất'],['popular','Được yêu thích nhất'],['price-asc','Giá: thấp đến cao'],['price-desc','Giá: cao đến thấp']].map(([v,l])=>`<option value="${v}" ${(params.get('sort')||'featured')===v?'selected':''}>${l}</option>`).join('')}</select></div>${data.items.length?grid(data.items,{catalog:true}):empty('Chưa tìm thấy thiết kế phù hợp','Thử đổi từ khóa hoặc bớt một vài bộ lọc để khám phá thêm nhé.','Xem tất cả','/san-pham','search')}${data.pages>1?`<div class="pagination">${Array.from({length:data.pages},(_,i)=>`<button data-page="${i+1}" class="${data.page===i+1?'active':''}" aria-label="Trang ${i+1}">${i+1}</button>`).join('')}</div>`:''}</div></div></section>`;
}
function detailMarkup(p,modal=false) {
  const available=p.variants.filter(v=>v.stock>0);state.selectedVariant=available[0]?.id||null;
  let markup=`<div class="product-detail"><div class="detail-image"><img src="${esc(p.thumbnail)}" alt="${esc(p.name)}" width="700" height="900" fetchpriority="high">${p.original_price?'<span class="product-badge sale">ƯU ĐÃI ĐẶC BIỆT</span>':''}</div><div class="detail-copy"><span class="small-label">${esc(p.brand)} · ${esc(p.category)}</span><h1>${esc(p.name)}</h1><div class="detail-rating">${p.rating?`<span class="review-stars">${'★'.repeat(Math.round(p.rating))}${'☆'.repeat(5-Math.round(p.rating))}</span> ${p.rating} · ${p.review_count} đánh giá`:'Một thiết kế mới, chờ câu chuyện của bạn.'}</div><div class="detail-price">${money(p.price)}${p.original_price?`<span class="old-price">${money(p.original_price)}</span>`:''}</div><p class="detail-description">${esc(p.description)}</p><div class="detail-label"><span>Màu sắc: <b>${esc(p.color)}</b></span><span style="background:${colorHex[p.color]||'#b4a589'}" class="swatch"></span></div><div class="detail-label"><span>Chọn kích thước</span><a href="/thong-tin/kich-thuoc" data-link class="text-button" style="font-size:9px">Hướng dẫn kích thước</a></div><div class="size-list">${p.variants.map(v=>`<button class="size-button ${v.id===state.selectedVariant?'active':''}" data-variant="${v.id}" ${v.stock===0?'disabled':''}>${esc(v.size)}</button>`).join('')}</div><p class="detail-stock">${available.length?'Sẵn sàng trong tủ đồ của bạn':'Tạm hết hàng'}</p><div class="detail-actions"><button class="button primary" data-add-cart="${p.id}" ${available.length?'':'disabled'}>${icon('bag')} Thêm vào giỏ hàng</button><button class="icon-btn ${state.favorites.has(p.id)?'saved':''}" data-favorite="${p.id}" aria-label="Yêu thích sản phẩm">${icon('heart')}</button></div><div class="detail-perks"><div>${icon('truck')} Miễn phí vận chuyển cho đơn từ 999.000đ</div><div>${icon('return')} An tâm đổi trả trong vòng 30 ngày</div></div><div class="detail-meta"><span>Chất liệu: ${esc(p.material)}</span><span>Phong cách: ${esc(p.style)}</span></div>${modal?`<a class="underlined" href="/san-pham/${p.id}" data-link style="margin-top:22px">Xem đầy đủ thiết kế ${icon('arrow')}</a>`:''}</div></div>`;
  return enhanceDetailMarkup(p,markup,modal);
}
async function detailPage(id) {
  const [p,similar,reviews]=await Promise.all([api(`/products/${id}`),api(`/recommendations/similar/${id}`),api(`/products/${id}/reviews`)]);state.modalProduct=p;
  return `<section class="container page-space">${breadcrumb(p.name,'products')}${detailMarkup(p)}<div class="review-section"><h2>Những cảm nhận chân thành</h2>${reviews.length?reviews.map(r=>`<div class="review-item" data-simulated="${!!r.simulated}"><b>${esc(r.name)}</b> <span class="review-stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span><p>${esc(r.comment)}</p><time>${date(r.created_at)}</time></div>`).join(''):'<p class="form-hint">Chưa có đánh giá. Hãy là người đầu tiên kể câu chuyện của bạn với thiết kế này.</p>'}${state.user?`<form id="review-form" class="review-form" data-id="${id}"><div class="field"><label for="review-rating">Đánh giá của bạn</label><select id="review-rating" name="rating"><option value="5">★★★★★ — Rất yêu thích</option><option value="4">★★★★☆ — Hài lòng</option><option value="3">★★★☆☆ — Khá ổn</option><option value="2">★★☆☆☆ — Chưa hài lòng</option><option value="1">★☆☆☆☆ — Cần cải thiện</option></select></div><div class="field"><label for="review-comment">Chia sẻ cảm nhận</label><textarea name="comment" id="review-comment" required minlength="3" maxlength="2000" placeholder="Phom dáng, chất liệu hay cảm giác khi mặc…"></textarea></div><button class="button outline small" type="submit">Gửi đánh giá ${icon('arrow')}</button><div class="form-error"></div></form>`:'<a href="/tai-khoan" data-link class="underlined" style="margin-top:16px">Đăng nhập để chia sẻ cảm nhận →</a>'}</div><div class="section" style="padding-bottom:0"><div class="section-heading"><div><span class="small-label">CÙNG MỘT CẢM HỨNG</span><h2>Có thể bạn <em>cũng yêu.</em></h2><p>${esc(similar.message)}</p></div></div>${similar.items.length?grid(similar.items):empty('Một thiết kế thật riêng','Những lựa chọn cùng phong cách sẽ sớm xuất hiện.')}</div></section>`;
}
async function forYouPage() {
  const params=new URLSearchParams(location.search);const method=params.get('method')||'hybrid';const gender=params.get('gender')||'';const max=params.get('max_price')||'';
  const data=await api(`/recommendations/${method}?k=18&gender=${encodeURIComponent(gender)}${max?'&max_price='+max:''}`);
  return atelierForYou(data,{method,gender,max});
}
function authMarkup() {
  const register=state.authMode==='register';
  return `<section class="container page-space">${breadcrumb('Tài khoản')}<div class="auth-page"><div class="auth-art"><img src="/static/images/hero-beige.jpg" alt="Phong cách thanh lịch của VELASTYLE" style="object-position:62% center"><h2>Một tủ đồ.<br>Rất nhiều phiên bản<br>của chính bạn.</h2></div><div class="auth-form"><span class="small-label">CHÀO MỪNG ĐẾN VELASTYLE</span><h1>${register?'Bắt đầu câu chuyện mới.':'Thật vui được gặp lại bạn.'}</h1><p>${register?'Một tài khoản, cả thế giới cảm hứng dành riêng cho bạn.':'Đăng nhập để tìm lại những thiết kế bạn yêu.'}</p><div class="auth-tabs"><button class="${!register?'active':''}" data-auth-mode="login">Đăng nhập</button><button class="${register?'active':''}" data-auth-mode="register">Đăng ký</button></div><form id="auth-form">${register?'<div class="field"><label for="full-name">Tên của bạn</label><input id="full-name" name="full_name" required minlength="2" maxlength="100" placeholder="Chúng mình nên gọi bạn là gì?" autocomplete="name"></div>':''}<div class="field"><label for="email">Email</label><input type="email" id="email" name="email" required placeholder="ban@example.com" autocomplete="email" maxlength="200"></div><div class="field"><label for="password">Mật khẩu</label><input type="password" id="password" name="password" required ${register?'minlength="8"':''} maxlength="128" placeholder="${register?'Ít nhất 8 ký tự':'Mật khẩu của bạn'}" autocomplete="${register?'new-password':'current-password'}"></div><div class="form-error"></div><div class="form-actions"><button type="submit" class="button primary wide">${register?'Tạo tài khoản':'Đăng nhập'} ${icon('arrow')}</button></div></form><p class="form-hint" style="margin-top:17px">Khi tiếp tục, bạn đồng ý với <a href="/thong-tin/bao-mat" data-link style="text-decoration:underline">chính sách quyền riêng tư</a>.</p><div class="demo-note">Trải nghiệm với tài khoản mẫu<br><button data-demo="user">Khách hàng: linh@velastyle.vn</button><br><button data-demo="admin">Quản trị: admin@velastyle.vn</button><br>Mật khẩu dùng thử: <b>Vela@12345</b></div></div></div></section>`;
}
function accountSidebar() {return `<aside class="account-side"><div class="avatar">${esc(state.user.full_name[0])}</div><h3>${esc(state.user.full_name)}</h3><p>${esc(state.user.email)}</p><nav><a href="/tai-khoan" data-link>${icon('user')} Hồ sơ & sở thích</a><a href="/don-hang" data-link>${icon('box')} Đơn hàng của tôi</a><a href="/yeu-thich" data-link>${icon('heart')} Thiết kế yêu thích</a><a href="/danh-rieng-cho-ban" data-link>${icon('sparkles')} Dành riêng cho bạn</a>${state.user.role==='admin'?`<a href="/quan-tri" data-link>${icon('grid')} Quản trị cửa hàng</a>`:''}<button data-action="logout">${icon('logout')} Đăng xuất</button></nav></aside>`;}
async function accountPage() {
  if(!state.user)return authMarkup();
  const p=state.user.preferences;const history=await api('/history');
  return `<section class="container page-space">${breadcrumb('Tài khoản của bạn')}<div class="account-layout">${accountSidebar()}<div><form id="profile-form" class="profile-form"><span class="small-label">RẤT RIÊNG, RẤT BẠN</span><h2>Gu của bạn. Cảm hứng của chúng mình.</h2><div class="field"><label for="profile-name">Họ và tên</label><input id="profile-name" name="full_name" value="${esc(state.user.full_name)}" required minlength="2" maxlength="100" autocomplete="name"></div><div class="field-row"><div class="field"><label for="profile-gender">Bạn quan tâm</label><select id="profile-gender" name="gender"><option value="">Tất cả</option>${['Nữ','Nam','Unisex','Phụ kiện'].map(v=>`<option ${p.gender===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="profile-style">Phong cách yêu thích</label><select id="profile-style" name="style"><option value="">Tự do khám phá</option>${['Nữ tính','Thanh lịch','Tối giản','Năng động'].map(v=>`<option ${p.style===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="field-row"><div class="field"><label for="profile-color">Màu sắc yêu thích</label><select id="profile-color" name="color"><option value="">Mọi màu sắc</option>${Object.keys(colorHex).map(v=>`<option ${p.color===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="profile-budget">Ngân sách mỗi thiết kế (đ)</label><input id="profile-budget" type="number" name="budget" min="0" max="100000000" value="${p.budget||2000000}" required></div></div><div class="form-error"></div><button class="button primary" type="submit">Lưu sở thích của bạn ${icon('check')}</button></form>${history.length?`<div class="section-heading" style="margin-top:50px"><div><span class="small-label">DẤU CHÂN PHONG CÁCH</span><h2>Bạn đã <em>ghé xem.</em></h2></div></div>${grid(history.slice(0,6))}`:''}</div></div></section>`;
}
async function favoritesPage() {
  const items=state.user?await api('/favorites'):[];
  return `<section class="container page-space">${breadcrumb('Yêu thích')}<div class="page-intro"><span class="small-label">MỘT GÓC NHỎ ĐỂ YÊU</span><h1>Những điều khiến bạn <em>rung động.</em></h1><p>Một góc nhỏ lưu lại những thiết kế bạn yêu, để cảm hứng luôn ở đây khi bạn cần.</p></div>${items.length?grid(items):empty(state.user?'Tủ đồ yêu thích đang chờ bạn':'Lưu lại những thiết kế bạn yêu',state.user?'Chạm vào trái tim trên mỗi thiết kế để lưu vào góc nhỏ này.':'Đăng nhập để những lựa chọn của bạn luôn được lưu lại.',state.user?'Tìm thiết kế yêu thích':'Đăng nhập',state.user?'/san-pham':'/tai-khoan','heart')}</section>`;
}
function summary(cart,checkout=false) {
  return `<aside class="order-summary"><h2>Một lựa chọn thật đẹp.</h2><div class="summary-line"><span>Tạm tính (${cart.count} sản phẩm)</span><span>${money(cart.total)}</span></div><div class="summary-line"><span>Phí vận chuyển</span><span>${cart.shipping?money(cart.shipping):'Miễn phí'}</span></div><div class="summary-line total"><span>Tổng cộng</span><span>${money(cart.total+cart.shipping)}</span></div>${checkout?`<p style="text-align:left;margin-bottom:13px">Đặt hàng mô phỏng, không thu tiền và không giao hàng thật.</p><button type="submit" form="checkout-form" class="button primary wide">Xác nhận đặt hàng ${icon('arrow')}</button>`:`<a href="/thanh-toan" data-link class="button primary wide">Tiến hành đặt hàng ${icon('arrow')}</a>`}<p>${icon('shield')} Thông tin của bạn được bảo vệ.</p></aside>`;
}
async function cartPage() {
  if(state.user)state.cart=await api('/cart');const c=state.cart;
  return `<section class="container page-space">${breadcrumb('Giỏ hàng')}<div class="page-intro"><span class="small-label">NIỀM VUI TRONG TỦ ĐỒ</span><h1>Tủ đồ sắp có thêm niềm vui.</h1><p>${c.count?`${c.count} thiết kế đã được bạn lựa chọn.`:'Mỗi món đồ đẹp đều bắt đầu từ một lần khám phá.'}</p></div>${c.items.length?`<div class="cart-layout"><div>${c.items.map(item=>`<article class="cart-item"><img src="${esc(item.product.thumbnail)}" alt="${esc(item.product.name)}"><div><h3><a href="/san-pham/${item.product.id}" data-link>${esc(item.product.name)}</a></h3><p>${esc(item.product.color)} · Kích thước ${esc(item.size)}</p><div class="quantity-control"><button data-quantity-id="${item.id}" data-quantity="${item.quantity-1}" aria-label="Giảm số lượng" ${item.quantity===1?'disabled':''}>−</button><span>${item.quantity}</span><button data-quantity-id="${item.id}" data-quantity="${item.quantity+1}" aria-label="Tăng số lượng" ${item.quantity>=Math.min(20,item.stock)?'disabled':''}>+</button></div></div><div class="cart-item-total">${money(item.product.price*item.quantity)}<button data-remove-cart="${item.id}">Xóa</button></div></article>`).join('')}<p class="cart-shipping-note">${icon('truck')}${c.shipping?`Thêm ${money(999000-c.total)} để được miễn phí vận chuyển.`:'Đơn hàng của bạn được miễn phí vận chuyển.'}</p><a class="underlined" href="/san-pham" data-link style="margin-top:24px">Tiếp tục khám phá →</a></div>${summary(c)}</div>`:empty('Một khoảng trống cho những điều đẹp','Chọn vài thiết kế bạn yêu để bắt đầu câu chuyện phong cách mới.',state.user?'Khám phá bộ sưu tập':'Đăng nhập để mua sắm',state.user?'/san-pham':'/tai-khoan')}</section>`;
}
async function checkoutPage() {
  if(!state.user)return authMarkup();state.cart=await api('/cart');
  if(!state.cart.items.length)return `<section class="container page-space">${empty('Giỏ hàng đang trống','Hãy chọn một thiết kế trước khi đặt hàng.')}</section>`;
  return `<section class="container page-space">${breadcrumb('Hoàn tất lựa chọn')}<div class="page-intro"><span class="small-label">SẮP THÀNH CỦA BẠN</span><h1>Một bước nữa thôi.</h1><p>Kiểm tra thông tin để hoàn tất đơn hàng mô phỏng của bạn.</p></div><div class="checkout-layout"><form id="checkout-form"><h2 style="font:27px var(--serif);margin-bottom:25px">Thông tin nhận hàng</h2><div class="field-row"><div class="field"><label for="checkout-name">Họ và tên người nhận</label><input id="checkout-name" name="full_name" value="${esc(state.user.full_name)}" required minlength="2" maxlength="100" autocomplete="name"></div><div class="field"><label for="checkout-phone">Số điện thoại</label><input type="tel" id="checkout-phone" name="phone" pattern="0[0-9]{9,10}" placeholder="09xxxxxxxx" required maxlength="11" autocomplete="tel"></div></div><div class="field"><label for="checkout-address">Địa chỉ nhận hàng</label><textarea id="checkout-address" name="address" placeholder="Số nhà, đường, phường/xã, tỉnh/thành phố" required minlength="10" maxlength="500" autocomplete="street-address"></textarea></div><div class="admin-note">Thanh toán mô phỏng. Không cần nhập thông tin thẻ ngân hàng.</div><div class="form-error"></div><h2 style="font:24px var(--serif);margin:28px 0 20px">Những thiết kế bạn chọn</h2>${state.cart.items.map(i=>`<div class="order-line"><img src="${esc(i.product.thumbnail)}" alt="${esc(i.product.name)}"><div>${esc(i.product.name)}<br><span>${esc(i.size)} · ${i.quantity} sản phẩm · ${money(i.product.price)}</span></div></div>`).join('')}</form>${summary(state.cart,true)}</div></section>`;
}
async function ordersPage() {
  if(!state.user)return authMarkup();const items=await api('/orders');
  return `<section class="container page-space">${breadcrumb('Đơn hàng của tôi')}<div class="account-layout">${accountSidebar()}<div><div class="page-intro"><span class="small-label">HÀNH TRÌNH PHONG CÁCH</span><h1>Những lựa chọn đã thành câu chuyện.</h1><p>Lịch sử đơn hàng mô phỏng của bạn.</p></div>${items.length?items.map(o=>`<article class="order-card"><div class="order-card-head"><div><b>Đơn hàng #VELA${String(o.id).padStart(5,'0')}</b><br><span class="form-hint">${date(o.created_at)}</span></div><span class="order-status">${esc(o.status)}</span></div>${o.items.map(i=>`<div class="order-line"><img src="${esc(i.thumbnail)}" alt="${esc(i.name)}"><div>${esc(i.name)}<br><span>Kích thước ${esc(i.size)} · SL ${i.quantity} · ${money(i.unit_price)}</span></div></div>`).join('')}<div class="order-card-total">Tổng cộng: <b>${money(o.total)}</b></div></article>`).join(''):empty('Câu chuyện mua sắm chưa bắt đầu','Những đơn hàng của bạn sẽ được lưu tại đây.')}</div></div></section>`;
}
function imageSearchPage() {
  return `<section class="container page-space">${breadcrumb('Tìm bằng hình ảnh')}<div class="page-intro"><span class="small-label">NHÌN THẤY. YÊU THÍCH. TÌM THẤY.</span><h1>Cảm hứng đến từ một tấm ảnh.</h1><p>Một chiếc váy lướt qua, một phong cách bạn thích. Tải ảnh lên để tìm những thiết kế có hình ảnh tương đồng bằng CLIP.</p></div><label class="upload-area" id="image-drop" for="image-file">${icon('camera')}<h2>Cho chúng mình xem cảm hứng của bạn.</h2><p>Kéo thả ảnh vào đây hoặc nhấn để chọn ảnh</p><span class="button outline small">${icon('upload')} Chọn hình ảnh</span><span class="form-hint">JPG, PNG, WebP · Tối đa 5 MB · 25 megapixel</span></label><input id="image-file" type="file" accept="image/jpeg,image/png,image/webp" hidden><div id="image-search-output"></div></section>`;
}
async function submitImage(file) {
  if(!requireLogin())return;if(!file)return;
  if(file.size>5*1024*1024){toast('Ảnh tối đa 5 MB. Vui lòng chọn ảnh nhỏ hơn.',true);return;}
  const output=$('#image-search-output');const url=URL.createObjectURL(file);
  output.innerHTML=`<div class="image-search-layout"><div><span class="small-label">CẢM HỨNG CỦA BẠN</span><img src="${url}" class="image-preview" alt="Ảnh bạn vừa tải lên" style="margin-top:15px"></div><div class="image-search-results"><p class="recommendation-note">Đang tìm những thiết kế đồng điệu với ảnh của bạn…</p>${skeletons(4)}</div></div>`;
  const form=new FormData();form.append('file',file);
  try{const data=await api('/recommendations/image-search',{method:'POST',body:form});if(!$('.image-search-results'))return;$('.image-search-results').innerHTML=`<p class="recommendation-note">${data.items.length} thiết kế có hình ảnh tương đồng · CLIP ViT-B/32</p>${grid(data.items,{score:true})}`;}
  catch(err){if($('.image-search-results'))$('.image-search-results').innerHTML=empty('Cảm hứng cần thêm một chút chuẩn bị',err.message,'','','camera');}
}
async function infoPage(slug) {const p=await api('/info/'+encodeURIComponent(slug));return `<section class="info-page">${breadcrumb(p.title)}<span class="small-label">VELASTYLE, VỚI TẤT CẢ QUAN TÂM</span><h1>${esc(p.title)}</h1><p>${esc(p.content)}</p><a class="underlined" href="/san-pham" data-link style="margin-top:35px">Trở lại với cảm hứng ${icon('arrow')}</a></section>`;}

const adminNav=[['','Tổng quan','grid'],['san-pham','Sản phẩm','bag'],['danh-muc','Danh mục','grid'],['thuong-hieu','Thương hiệu','box'],['nguoi-dung','Người dùng','user'],['don-hang','Đơn hàng','box'],['tuong-tac','Tương tác','heart'],['ai','Gợi ý & mô hình AI','sparkles'],['danh-gia','Đánh giá mô hình','chart'],['dataset','Dữ liệu & dataset','database'],['cai-dat','Cài đặt','settings']];
const methodLabels={collaborative:'Lọc cộng tác',clip:'CLIP',hybrid:'Hybrid'};
const eventLabels={view:'Lượt xem',favorite:'Yêu thích',cart:'Thêm giỏ',purchase:'Mua mô phỏng'};
function adminShell(section,content) {return `<div class="admin-wrapper"><aside class="admin-sidebar"><span class="small-label">VELASTYLE / QUẢN TRỊ</span><nav>${adminNav.map(([path,label,name])=>`<a href="/quan-tri${path?'/'+path:''}" data-link class="${section===path?'active':''}">${icon(name)} ${label}</a>`).join('')}</nav><a href="/" data-link class="underlined" style="margin:24px 13px 0">Về cửa hàng ↗</a></aside><section class="admin-main">${content}</section></div>`;}
function adminHead(title,description,action='') {return `<div class="admin-head"><div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function table(headers,rows) {return `<div class="admin-table-wrap"><table class="admin-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" style="text-align:center;padding:35px;color:#929581">Chưa có dữ liệu.</td></tr>`}</tbody></table></div>`;}
function chart(items,{percent=false,precision=1}={}) {const max=Math.max(...items.map(i=>i.value),.001);return `<div class="bar-chart">${items.map(i=>`<div class="bar-row"><span>${esc(i.label)}</span><div class="bar-track"><div class="bar-value" style="width:${Math.max(0,i.value/max*100)}%"></div></div><span>${percent?(i.value*100).toFixed(precision)+'%':Number(i.value).toFixed(precision)}</span></div>`).join('')}</div>`;}
function runList(runs) {return runs.length?runs.map(r=>`<div class="run-item"><span>${esc({'generate-embeddings':'Tạo đặc trưng CLIP','rebuild-cf':'Xây dựng lọc cộng tác','evaluate':'Đánh giá mô hình'}[r.kind]||r.kind)} · #${r.id}</span><span class="status-pill ${r.status}">${{completed:'Hoàn tất',running:'Đang xử lý',failed:'Có lỗi'}[r.status]}</span><p>${esc(r.message)} · ${date(r.created_at)}</p></div>`).join(''):'<p class="form-hint">Chưa có tác vụ nào được thực hiện.</p>';}
async function adminPage(section='') {
  if(!state.user)return authMarkup();
  if(state.user.role!=='admin')return `<section class="container page-space">${empty('Góc này dành cho quản trị viên','Bạn vẫn có cả một thế giới cảm hứng để khám phá.','Về cửa hàng','/','shield')}</section>`;
  let content='';
  if(!section){
    const d=await api('/admin/dashboard');
    content=adminHead('Một ngày mới tại VELASTYLE.','Tổng quan cửa hàng, tương tác và hệ gợi ý.')+`<div class="admin-note">Dữ liệu thử nghiệm: ${d.simulated_interactions} tương tác được mô phỏng. Đơn hàng và doanh thu là mô phỏng.</div><div class="admin-metrics">${[['SẢN PHẨM',d.products,'Thiết kế đang hoạt động'],['NGƯỜI DÙNG',d.users,'Gồm tài khoản mô phỏng'],['ĐƠN HÀNG',d.orders,'Đơn được lưu trong SQLite'],['DOANH THU',money(d.revenue),'Giá trị đơn hàng mô phỏng']].map(([l,v,p])=>`<article class="metric-card"><span class="small-label">${l}</span><strong>${v}</strong><p>${p}</p></article>`).join('')}</div><div class="admin-panels"><article class="admin-panel"><h2>Tương tác với sản phẩm</h2>${chart(d.events.map(e=>({label:eventLabels[e.name]||e.name,value:e.count})),{precision:0})}<p style="margin-top:20px">Tổng ${d.interactions} tương tác được ghi nhận.</p></article><article class="admin-panel"><h2>Doanh thu theo ngày</h2>${d.revenue_chart.length?chart(d.revenue_chart.map(r=>({label:r.date,value:r.total})),{precision:0}):'<p>Chưa có đơn hàng. Biểu đồ sẽ xuất hiện sau khi đơn đầu tiên được tạo.</p>'}</article></div><div class="admin-panel"><h2>Những thiết kế được quan tâm</h2>${table(['Thiết kế','Điểm tương tác','Giá'],d.popular.map(p=>[`<div class="admin-product-cell"><img src="${esc(p.thumbnail)}" alt="">${esc(p.name)}</div>`,p.interactions_score,money(p.price)]))}</div><div class="admin-panel"><h2>Nhật ký mô hình gần nhất</h2>${runList(d.runs)}</div>`;
  }else if(section==='san-pham'){
    state.adminProducts=await api('/admin/products');
    content=adminHead('Quản lý thiết kế',`${state.adminProducts.length} sản phẩm trong bộ sưu tập.`,`<button class="button primary small" data-action="admin-add-product">${icon('plus')} Thêm thiết kế</button>`)+table(['Thiết kế','Danh mục','Giá bán','Tồn kho','Thao tác'],state.adminProducts.map(p=>[`<div class="admin-product-cell"><img src="${esc(p.thumbnail)}" alt="">${esc(p.name)}</div>`,esc(p.category),money(p.price),p.stock,`<button class="table-action" data-edit-product="${p.id}">Chỉnh sửa</button><button class="table-action danger" data-archive-product="${p.id}">Ngừng bán</button>`]));
  }else if(['danh-muc','thuong-hieu'].includes(section)){
    const kind=section==='danh-muc'?'categories':'brands';const items=await api('/'+kind);state.taxonomy=items;
    content=adminHead(section==='danh-muc'?'Danh mục sản phẩm':'Những thương hiệu',`${items.length} ${section==='danh-muc'?'danh mục':'thương hiệu'} đang được quản lý.`,`<button class="button primary small" data-add-taxonomy="${kind}">${icon('plus')} Thêm mới</button>`)+table(['ID','Tên','Mô tả','Thao tác'],items.map(t=>[t.id,esc(t.name),esc(t.description),`<button class="table-action" data-edit-taxonomy="${t.id}" data-kind="${kind}">Sửa</button><button class="table-action danger" data-delete-taxonomy="${t.id}" data-kind="${kind}">Xóa</button>`]));
  }else if(section==='nguoi-dung'){
    const users=await api('/admin/users');content=adminHead('Những người đồng hành',`${users.length} tài khoản trong hệ thống.`)+table(['Họ tên','Email','Vai trò','Dữ liệu','Ngày tham gia'],users.map(u=>[esc(u.name),esc(u.email),u.role==='admin'?'Quản trị':'Khách hàng',u.simulated?'<span class="status-pill">Mô phỏng</span>':'Đăng ký thật',date(u.created_at)]));
  }else if(section==='don-hang'){
    const orders=await api('/admin/orders');state.adminOrders=orders;content=adminHead('Những lựa chọn đã được gửi gắm','Quản lý và cập nhật trạng thái đơn hàng mô phỏng.')+table(['Mã đơn','Người nhận','Tổng tiền','Ngày tạo','Trạng thái','Chi tiết'],orders.map(o=>['#VELA'+String(o.id).padStart(5,'0'),esc(o.full_name),money(o.total),date(o.created_at),`<select data-order-status="${o.id}" aria-label="Trạng thái đơn ${o.id}">${['Đã xác nhận','Đang giao','Đã giao','Đã hủy'].map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select>`,`<button class="table-action" data-order-detail="${o.id}">Xem đơn</button>`]));
  }else if(section==='tuong-tac'){
    const events=await api('/admin/interactions');content=adminHead('Từng tương tác, một tín hiệu','100 tương tác gần nhất. Hành vi mua và thêm giỏ chỉ được ghi từ luồng thật.')+table(['Người dùng','Thiết kế','Hành vi','Trọng số','Nguồn','Ngày'],events.map(e=>[esc(e.user),esc(e.product),eventLabels[e.type],e.weight,e.simulated?'Mô phỏng':'Ứng dụng',date(e.created_at)]));
  }else if(section==='ai'||section==='cai-dat'){
    const a=await api('/admin/ai/status');content=adminHead(section==='ai'?'Một hệ gợi ý, nhiều góc nhìn.':'Cấu hình trải nghiệm','Quản lý CLIP, lọc cộng tác và trọng số kết hợp.')+`<div class="admin-ai-grid"><article class="admin-panel"><h2>Đặc trưng hình ảnh & văn bản</h2><div class="ai-status-line"><span>Mô hình</span><b>${esc(a.model)}</b></div><div class="ai-status-line"><span>Thiết bị</span><b>${esc(a.device.toUpperCase())}</b></div><div class="ai-status-line"><span>Embedding hợp lệ</span><b>${a.embeddings} / ${a.products}</b></div><div class="ai-status-line"><span>Trạng thái</span><span class="status-pill">${a.ready?'Đã có đặc trưng CLIP':'Chờ tạo đặc trưng'}</span></div><p>Ảnh 60% + văn bản 40%, chuẩn hóa L2. Chỉ cập nhật khi nội dung hoặc mô hình thay đổi. Lần chạy đầu cần tải mô hình từ Hugging Face.</p><div class="ai-task-buttons"><button class="button primary small" data-ai-task="generate-embeddings">${icon('sparkles')} Tạo / cập nhật CLIP</button></div></article><article class="admin-panel"><h2>Lọc cộng tác & kết hợp</h2><p>Item-based CF từ ma trận thưa user–item và cosine similarity. Trọng số: xem 1, yêu thích 3, giỏ hàng 4, mua 5. Trọng số CF giảm khi lịch sử còn ít.</p><form id="ai-settings-form"><label class="form-hint" for="alpha">Trọng số α cho Collaborative Filtering</label><div class="range-field"><input type="range" id="alpha" name="alpha" min="0" max="1" step="0.05" value="${a.alpha}"><output id="alpha-value">${a.alpha.toFixed(2)}</output></div><p class="form-hint">Hybrid = α × CF + (1 − α) × CLIP</p><div class="ai-task-buttons"><button type="submit" class="button outline small">Lưu trọng số ${icon('check')}</button><button type="button" class="button primary small" data-ai-task="rebuild-cf">Xây dựng lại CF ${icon('return')}</button></div><div class="form-error"></div></form></article></div><article class="admin-panel"><h2>Nhật ký thực thi</h2><div id="ai-runs">${runList(a.runs)}</div></article>`;
    if(a.runs.some(r=>r.status==='running'))schedulePoll();
  }else if(section==='danh-gia'){
    const evaluations=await api('/admin/evaluations');const last=evaluations[0];
    content=adminHead('Hiểu điều gì thực sự phù hợp.','So sánh ba mô hình bằng chỉ số tính từ kết quả xếp hạng thực tế.',`<div style="display:flex;gap:9px"><select id="evaluation-k" aria-label="Chọn K" style="background:transparent;border:1px solid var(--line);padding:7px">${[5,10,20].map(k=>`<option value="${k}" ${(last?.result.results[0]?.k||10)===k?'selected':''}>K = ${k}</option>`).join('')}</select><button class="button primary small" data-ai-task="evaluate">${icon('chart')} Chạy đánh giá</button></div>`);
    if(!last)content+=empty('Chưa có kết quả đánh giá','Tạo đầy đủ embedding CLIP rồi chạy đánh giá. Hệ thống không hiển thị chỉ số khi chưa có dữ liệu hợp lệ.','','','chart');
    else{const r=last.result;content+=`<div class="admin-note">${r.simulated?'Kết quả trên tương tác MÔ PHỎNG, không phải thực nghiệm khách hàng thật. ':''}${r.users} người dùng · ${r.train_interactions} tương tác train · α = ${r.alpha} · ${date(last.created_at)}</div><div class="evaluation-chart-grid">${[['precision_at_k','Precision@K'],['recall_at_k','Recall@K'],['ndcg_at_k','NDCG@K'],['inference_time_ms','Thời gian suy luận (ms)']].map(([key,label])=>`<article class="admin-panel"><h2>${label}</h2>${chart(r.results.map(v=>({label:methodLabels[v.model_name],value:v[key]})),{percent:key!=='inference_time_ms',precision:key==='inference_time_ms'?3:1})}</article>`).join('')}</div>${table(['Phương pháp','K','Precision','Recall','NDCG','Hit Rate','Coverage','Thời gian'],r.results.map(v=>[methodLabels[v.model_name],v.k,...['precision_at_k','recall_at_k','ndcg_at_k','hit_rate_at_k','coverage'].map(key=>(v[key]*100).toFixed(2)+'%'),v.inference_time_ms.toFixed(3)+' ms']))}<article class="admin-panel" style="margin-top:25px"><h2>Quy trình thực nghiệm</h2><p>${esc(r.protocol)}</p><p style="margin-top:12px">${esc(r.latency_scope)}</p><p style="margin-top:12px">Precision chia cho K cố định; mỗi người có 1 sản phẩm test nên Recall và Hit Rate bằng nhau. K lớn so với catalog nhỏ có thể làm Recall cao; cần mở rộng dataset thật trước khi rút ra kết luận.</p></article>`;}
  }else if(section==='dataset'){
    const d=await api('/admin/dataset');content=adminHead('Dữ liệu tốt, gợi ý có ý nghĩa.','Nguồn dữ liệu, trạng thái ảnh và nhập catalog.')+`<div class="admin-metrics">${[['SẢN PHẨM',d.products],['ẢNH HỢP LỆ',d.valid_images],['TÀI KHOẢN MÔ PHỎNG',d.simulated_users],['TƯƠNG TÁC MÔ PHỎNG',d.simulated_interactions]].map(([l,v])=>`<article class="metric-card"><span class="small-label">${l}</span><strong>${v}</strong></article>`).join('')}</div><article class="admin-panel"><h2>Nguồn dữ liệu</h2><p>${esc(d.source)}</p><p style="margin-top:13px">Catalog hiện có ${d.products} thiết kế có ảnh riêng, ${d.simulated_users} tài khoản và ${d.simulated_interactions} tương tác mô phỏng. Ảnh và metadata nguồn được lưu trong manifest; giá, thông tin mua hàng và lịch sử seed là minh họa.</p></article><article class="admin-panel"><h2>Nhập dữ liệu CSV trên máy</h2><p>Chạy lệnh trong thư mục dự án. Ảnh phải nằm trong static/images hoặc static/uploads và có đường dẫn /static/... hợp lệ. Bản ghi trùng tên được bỏ qua; lỗi được báo theo dòng.</p><div class="dataset-columns">python scripts/import_dataset.py data/raw/products.csv</div><p style="margin-top:17px">Các cột hỗ trợ</p><div class="dataset-columns">${d.csv_columns.join(', ')}</div></article>`;
  }else content=adminHead('Không tìm thấy trang quản trị','Chọn một mục trong thanh điều hướng.');
  return adminShell(section,content);
}

async function render() {
  document.body.classList.add('is-navigating');
  const token=++state.pageToken;clearTimeout(state.pollTimer);const path=decodeURI(location.pathname);const params=new URLSearchParams(location.search);
  $$('[data-nav]').forEach(a=>a.classList.remove('active'));
  const nav=path==='/'?'home':path==='/danh-rieng-cho-ban'?'foryou':params.get('gender')==='Nữ'?'women':params.get('gender')==='Nam'?'men':params.get('gender')==='Phụ kiện'?'accessories':params.get('sort')==='newest'?'new':'';
  $(`[data-nav="${nav}"]`)?.classList.add('active');
  try{
    let html;
    if(path==='/')html=await homePage();
    else if(path==='/san-pham')html=await catalogPage();
    else if(/^\/san-pham\/\d+$/.test(path))html=await detailPage(+path.split('/').pop());
    else if(path==='/danh-rieng-cho-ban')html=await forYouPage();
    else if(path==='/tai-khoan')html=await accountPage();
    else if(path==='/yeu-thich')html=await favoritesPage();
    else if(path==='/gio-hang')html=await cartPage();
    else if(path==='/thanh-toan')html=await checkoutPage();
    else if(path==='/don-hang')html=await ordersPage();
    else if(path==='/tim-bang-anh')html=imageSearchPage();
    else if(path==='/cam-hung'||path.startsWith('/cam-hung/'))html=await journalPage(path.split('/')[2]||'');
    else if(path.startsWith('/thong-tin/'))html=await infoPage(path.split('/').pop());
    else if(path==='/quan-tri'||path.startsWith('/quan-tri/'))html=await adminPage(path.split('/')[2]||'');
    else html=`<section class="container page-space">${empty('Hình như bạn đang lạc vào một trang mới','Trở lại bộ sưu tập để tiếp tục khám phá nhé.')}</section>`;
    if(token!==state.pageToken)return;$('#main').innerHTML=html;badges();document.title=(path==='/'?'Phong cách là chính bạn':$('#main h1')?.textContent||'Khám phá phong cách')+' — VELASTYLE';refreshExperience();
    if($('#image-drop')){const area=$('#image-drop');['dragenter','dragover'].forEach(type=>area.addEventListener(type,e=>{e.preventDefault();area.classList.add('dragover');}));['dragleave','drop'].forEach(type=>area.addEventListener(type,e=>{e.preventDefault();area.classList.remove('dragover');if(type==='drop')submitImage(e.dataTransfer.files[0]);}));}
  }catch(err){document.body.classList.remove('is-navigating');if(token!==state.pageToken)return;$('#main').innerHTML=`<section class="container page-space">${empty(err.status===404?'Thiết kế này chưa có trong tủ đồ':'Chưa thể mở cảm hứng',err.message,'Khám phá bộ sưu tập','/san-pham','search')}</section>`;}
}
let modalPreviousFocus=null;
function showModal(html,small=false) {modalPreviousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${small?'small-modal':''}" role="dialog" aria-modal="true" aria-label="Thông tin thiết kế"><button class="icon-btn modal-close" data-action="close-modal" aria-label="Đóng">${icon('close')}</button>${html}</section></div>`;document.body.classList.add('modal-open');$('.modal-close').focus();}
function closeModal(){if(!$('#modal-root').innerHTML)return;$('#modal-root').innerHTML='';document.body.classList.remove('modal-open');modalPreviousFocus?.focus?.();}
async function openQuick(id) {const p=await api('/products/'+id);state.modalProduct=p;showModal(detailMarkup(p,true));}
function productForm(p=null) {
  const value=(key,fallback='')=>esc(p?.[key]??fallback);
  const selected=(id,current)=>+id===+current?'selected':'';
  showModal(`<h2>${p?'Chỉnh sửa thiết kế':'Thêm thiết kế mới'}</h2><form id="admin-product-form" data-id="${p?.id||''}"><div class="field"><label for="product-name">Tên thiết kế</label><input id="product-name" name="name" value="${value('name')}" required minlength="3" maxlength="150"></div><div class="field-row"><div class="field"><label for="product-price">Giá bán (đ)</label><input id="product-price" type="number" name="price" value="${value('price',890000)}" required min="1" max="100000000"></div><div class="field"><label for="product-original-price">Giá gốc (nếu có)</label><input id="product-original-price" type="number" name="original_price" value="${value('original_price')}" min="1"></div></div><div class="field-row"><div class="field"><label for="product-category">Danh mục</label><select id="product-category" name="category_id">${state.categories.map(c=>`<option value="${c.id}" ${selected(c.id,p?.category_id)}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label for="product-brand">Thương hiệu</label><select id="product-brand" name="brand_id">${state.brands.map(b=>`<option value="${b.id}" ${selected(b.id,p?.brand_id)}>${esc(b.name)}</option>`).join('')}</select></div></div><div class="field-row"><div class="field"><label for="product-gender">Dành cho</label><select id="product-gender" name="gender">${['Nữ','Nam','Unisex','Phụ kiện'].map(v=>`<option ${p?.gender===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="product-color">Màu sắc</label><select id="product-color" name="color">${Object.keys(colorHex).map(v=>`<option ${p?.color===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="field-row"><div class="field"><label for="product-material">Chất liệu</label><input id="product-material" name="material" value="${value('material','Cotton')}" required></div><div class="field"><label for="product-style">Phong cách</label><select id="product-style" name="style">${['Nữ tính','Thanh lịch','Tối giản','Năng động'].map(v=>`<option ${p?.style===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="field"><label for="product-description">Mô tả tiếng Việt</label><textarea id="product-description" name="description" required minlength="10" maxlength="5000">${value('description')}</textarea></div><div class="field"><label for="product-clip-text">Mô tả tiếng Anh cho CLIP (khuyến nghị)</label><input id="product-clip-text" name="clip_text" value="${value('clip_text')}" maxlength="1000" placeholder="A woman wearing a beige linen midi dress"></div><div class="field"><label for="product-photo-upload">Ảnh thiết kế thật</label><input id="product-photo-upload" name="photo" type="file" accept="image/jpeg,image/png,image/webp" ${p?'':'required'}><input type="hidden" name="thumbnail" value="${value('thumbnail')}">${p?`<img src="${value('thumbnail')}" alt="Ảnh hiện tại" style="width:70px;height:90px;margin-top:8px">`:''}<p class="form-hint">Tối đa 5 MB. JPG, PNG hoặc WebP.</p></div><div class="field-row"><div class="field"><label for="product-sizes">Kích thước (ngăn bởi dấu phẩy)</label><input id="product-sizes" name="sizes" value="${esc(p?.variants.map(v=>v.size).join(', ')||'S, M, L, XL')}" required></div><div class="field"><label for="product-stock">Tồn kho mỗi kích thước</label><input type="number" id="product-stock" name="stock" min="0" max="10000" value="${p?.variants[0]?.stock??20}" required></div></div><div class="form-error"></div><button type="submit" class="button primary wide">Lưu thiết kế ${icon('check')}</button></form>`,true);
}
function taxonomyForm(kind,item=null) {showModal(`<h2>${item?'Chỉnh sửa':'Thêm'} ${kind==='categories'?'danh mục':'thương hiệu'}</h2><form id="taxonomy-form" data-kind="${kind}" data-id="${item?.id||''}"><div class="field"><label for="taxonomy-name">Tên</label><input id="taxonomy-name" name="name" required minlength="2" maxlength="100" value="${esc(item?.name||'')}"></div><div class="field"><label for="taxonomy-description">Mô tả</label><textarea id="taxonomy-description" name="description" maxlength="1000">${esc(item?.description||'')}</textarea></div><div class="form-error"></div><button type="submit" class="button primary wide">Lưu thay đổi ${icon('check')}</button></form>`,true);}
function schedulePoll(){clearTimeout(state.pollTimer);state.pollTimer=setTimeout(async()=>{if(!location.pathname.startsWith('/quan-tri'))return;try{const data=await api('/admin/ai/status');if($('#ai-runs'))$('#ai-runs').innerHTML=runList(data.runs);if(data.runs.some(r=>r.status==='running'))schedulePoll();else{toast(data.runs[0]?.status==='failed'?'Tác vụ AI có lỗi. Xem nhật ký để biết chi tiết.':'Đã hoàn tất tác vụ AI.',data.runs[0]?.status==='failed');render();}}catch(err){toast(err.message,true);}},2500);}

document.addEventListener('click',async e=>{
  const link=e.target.closest('a[data-link]');
  if(link&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&e.button===0){e.preventDefault();go(link.getAttribute('href'));return;}
  const el=e.target.closest('button,[data-filter-color]');if(!el||el.disabled)return;
  try{
    const action=el.dataset.action;
    if(action==='search'){const panel=$('#search-panel');panel.hidden=!panel.hidden;if(!panel.hidden)$('#search-input').focus();}
    else if(action==='close-search')$('#search-panel').hidden=true;
    else if(action==='mobile-menu')$('#mobile-nav').hidden=!$('#mobile-nav').hidden;
    else if(action==='image-search')go('/tim-bang-anh');
    else if(action==='close-modal')closeModal();
    else if(action==='back-top')window.scrollTo({top:0,behavior:'smooth'});
    else if(action==='toggle-filters'){const open=$('#filter-sidebar').classList.toggle('mobile-open');studio.filtersOpen=open;document.body.classList.toggle('filters-open',open);el.setAttribute('aria-expanded',String(open));}
    else if(action==='clear-filters')go('/san-pham');
    else if(action==='logout'){await api('/auth/logout',{method:'POST'});await syncUser();toast('Hẹn gặp lại bạn, với thật nhiều cảm hứng mới.');go('/');}
    else if(action==='admin-add-product')productForm();
    if(el.dataset.homeTab)await changeHomeTab(el.dataset.homeTab);
    if(el.dataset.favorite){if(!requireLogin())return;const id=+el.dataset.favorite;const data=await api('/favorites/'+id,{method:'POST'});data.favorite?state.favorites.add(id):state.favorites.delete(id);badges();toast(data.favorite?'Đã cất vào góc yêu thích của bạn.':'Đã bỏ khỏi danh sách yêu thích.');if(location.pathname==='/yeu-thich')render();}
    if(el.dataset.quick)await openQuick(+el.dataset.quick);
    if(el.dataset.variant){state.selectedVariant=+el.dataset.variant;studio.quantity=1;updateDetailQuantity();$$('[data-variant]').forEach(b=>b.classList.toggle('active',+b.dataset.variant===state.selectedVariant));}
    if(el.dataset.addCart){if(!requireLogin())return;if(!state.selectedVariant){toast('Chọn một kích thước vừa vặn với bạn nhé.',true);return;}el.disabled=true;try{state.cart=await api('/cart',{method:'POST',body:{variant_id:state.selectedVariant,quantity:studio.quantity||1}});badges();closeModal();toast('Một lựa chọn thật đẹp. Đã thêm vào giỏ hàng.');}finally{el.disabled=false;}}
    if(el.dataset.authMode){state.authMode=el.dataset.authMode;render();}
    if(el.dataset.demo){if(state.authMode!=='login'){state.authMode='login';await render();}$('#email').value=el.dataset.demo==='admin'?'admin@velastyle.vn':'linh@velastyle.vn';$('#password').value='Vela@12345';$('#auth-form button[type=submit]').focus();}
    if(el.dataset.page)updateQuery({page:el.dataset.page});
    if(el.dataset.filterColor){const params=new URLSearchParams(location.search);updateQuery({color:params.get('color')===el.dataset.filterColor?'':el.dataset.filterColor,page:''});}
    if(el.dataset.method)updateQuery({method:el.dataset.method});
    if(el.dataset.quantityId){state.cart=await api('/cart/'+el.dataset.quantityId,{method:'PATCH',body:{quantity:+el.dataset.quantity}});badges();render();}
    if(el.dataset.removeCart){state.cart=await api('/cart/'+el.dataset.removeCart,{method:'DELETE'});badges();render();toast('Đã bỏ thiết kế khỏi giỏ hàng.');}
    if(el.dataset.editProduct)productForm(state.adminProducts.find(p=>p.id===+el.dataset.editProduct));
    if(el.dataset.archiveProduct){const id=+el.dataset.archiveProduct;showModal(`<h2>Ngừng bán thiết kế này?</h2><p style="font-size:12px;color:var(--muted);margin-bottom:25px">Thiết kế sẽ được lưu trữ để giữ nguyên lịch sử đơn hàng.</p><button class="button primary" data-confirm-archive="${id}">Xác nhận ngừng bán</button>`,true);}
    if(el.dataset.confirmArchive){await api('/admin/products/'+el.dataset.confirmArchive,{method:'DELETE'});closeModal();toast('Đã ngừng bán thiết kế.');render();}
    if(el.dataset.addTaxonomy)taxonomyForm(el.dataset.addTaxonomy);
    if(el.dataset.editTaxonomy)taxonomyForm(el.dataset.kind,state.taxonomy.find(t=>t.id===+el.dataset.editTaxonomy));
    if(el.dataset.deleteTaxonomy){showModal(`<h2>Xóa mục này?</h2><p class="form-hint" style="margin-bottom:25px">Chỉ có thể xóa mục chưa được sản phẩm sử dụng.</p><button class="button primary" data-confirm-taxonomy="${el.dataset.deleteTaxonomy}" data-kind="${el.dataset.kind}">Xác nhận xóa</button>`,true);}
    if(el.dataset.confirmTaxonomy){await api(`/admin/taxonomy/${el.dataset.kind}/${el.dataset.confirmTaxonomy}`,{method:'DELETE'});closeModal();await refreshTaxonomy();toast('Đã xóa.');render();}
    if(el.dataset.orderDetail){const o=state.adminOrders.find(o=>o.id===+el.dataset.orderDetail);showModal(`<h2>Đơn hàng #${o.id}</h2><p>${esc(o.full_name)} · ${esc(o.phone)}</p><p style="font-size:11px;color:var(--muted);margin:8px 0 20px">${esc(o.address)}</p>${o.items.map(i=>`<div class="order-line"><img src="${esc(i.thumbnail)}" alt=""><div>${esc(i.name)}<br><span>${esc(i.size)} · ${i.quantity} × ${money(i.unit_price)}</span></div></div>`).join('')}<p class="order-card-total">Tổng cộng: ${money(o.total)}</p>`,true);}
    if(el.dataset.aiTask){el.disabled=true;try{const k=$('#evaluation-k')?.value||10;await api('/admin/ai/'+el.dataset.aiTask+'?k='+k,{method:'POST'});toast('Đã bắt đầu tác vụ. Bạn có thể tiếp tục dùng website.');schedulePoll();if(location.pathname.includes('/ai'))render();}finally{el.disabled=false;}}
  }catch(err){toast(err.message,true);}
});
function updateQuery(changes) {const params=new URLSearchParams(location.search);Object.entries(changes).forEach(([k,v])=>v?params.set(k,v):params.delete(k));go(location.pathname+(params.size?'?'+params:''),{scroll:false});}
async function refreshTaxonomy(){[state.categories,state.brands]=await Promise.all([api('/categories'),api('/brands')]);}
document.addEventListener('change',async e=>{
  const el=e.target;
  if(el.closest('#filter-form')){const values=Object.fromEntries(new FormData($('#filter-form')));updateQuery({...values,sale:$('#filter-form [name=sale]')?.checked?'true':'',page:''});}
  if(el.id==='catalog-sort')updateQuery({sort:el.value,page:''});
  if(el.id==='recommend-gender')updateQuery({gender:el.value});
  if(el.id==='recommend-budget')updateQuery({max_price:el.value});
  if(el.id==='image-file')await submitImage(el.files[0]);
  if(el.dataset.orderStatus){try{await api('/admin/orders/'+el.dataset.orderStatus,{method:'PATCH',body:{status:el.value}});toast('Đã cập nhật trạng thái đơn hàng.');}catch(err){toast(err.message,true);render();}}
});
document.addEventListener('input',e=>{if(e.target.id==='alpha')$('#alpha-value').textContent=(+e.target.value).toFixed(2);});
document.addEventListener('submit',async e=>{
  const form=e.target;e.preventDefault();const values=Object.fromEntries(new FormData(form));const submit=$('button[type=submit]',form)||$(`button[form="${form.id}"]`);const error=$('.form-error',form);if(error)error.textContent='';
  try{
    if(form.id==='search-form'){go('/san-pham?q='+encodeURIComponent(values.q.trim()));return;}
    if(form.id==='catalog-search'){updateQuery({q:values.q.trim(),page:''});return;}
    if(submit)submit.disabled=true;
    if(form.id==='auth-form'){
      await api('/auth/'+state.authMode,{method:'POST',body:values});await syncUser();toast(state.authMode==='register'?'Chào mừng bạn đến với VELASTYLE.':'Chào mừng bạn trở lại.');const back=sessionStorage.getItem('vela_return');sessionStorage.removeItem('vela_return');go(back?.startsWith('/')&&!back.startsWith('//')?back:state.user.role==='admin'?'/quan-tri':'/danh-rieng-cho-ban');
    }else if(form.id==='profile-form'){state.user=await api('/profile',{method:'PUT',body:{...values,budget:+values.budget}});toast('Đã lưu sở thích. Chúng mình hiểu bạn thêm một chút.');render();}
    else if(form.id==='review-form'){await api('/products/'+form.dataset.id+'/reviews',{method:'POST',body:{rating:+values.rating,comment:values.comment}});toast('Cảm ơn bạn đã chia sẻ cảm nhận.');render();}
    else if(form.id==='checkout-form'){
      const order=await api('/orders',{method:'POST',body:values});state.cart={items:[],count:0,total:0,shipping:0};badges();$('#main').innerHTML=`<section class="container page-space"><div class="success-state"><div class="success-icon">✓</div><span class="small-label">CẢM ƠN BẠN ĐÃ CHỌN VELASTYLE</span><h1>Một lựa chọn thật đẹp, ${esc(state.user.full_name.split(' ').at(-1))}.</h1><p>Đơn hàng #VELA${String(order.id).padStart(5,'0')} đã được lưu thành công.<br>Tổng cộng: ${money(order.total)} · Thanh toán và giao hàng mô phỏng.</p><a class="button primary" href="/don-hang" data-link>Xem đơn hàng ${icon('box')}</a><a class="button outline" href="/san-pham" data-link>Tiếp tục khám phá ${icon('arrow')}</a></div></section>`;window.scrollTo(0,0);
    }else if(form.id==='ai-settings-form'){await api('/admin/ai/settings',{method:'PUT',body:{alpha:+values.alpha}});toast('Đã lưu trọng số kết hợp.');}
    else if(form.id==='admin-product-form'){
      let thumbnail=values.thumbnail;const photo=$('input[type=file]',form).files[0];if(photo){const body=new FormData();body.append('file',photo);thumbnail=(await api('/admin/uploads',{method:'POST',body})).path;}
      const payload={...values,thumbnail,price:+values.price,original_price:values.original_price?+values.original_price:null,category_id:+values.category_id,brand_id:+values.brand_id,stock:+values.stock,sizes:values.sizes.split(',').map(s=>s.trim()).filter(Boolean)};delete payload.photo;
      await api('/admin/products'+(form.dataset.id?'/'+form.dataset.id:''),{method:form.dataset.id?'PUT':'POST',body:payload});closeModal();toast('Đã lưu thiết kế vào bộ sưu tập.');render();
    }else if(form.id==='taxonomy-form'){await api('/admin/taxonomy/'+form.dataset.kind+(form.dataset.id?'/'+form.dataset.id:''),{method:form.dataset.id?'PUT':'POST',body:values});closeModal();await refreshTaxonomy();toast('Đã lưu thay đổi.');render();}
  }catch(err){if(error)error.textContent=err.message;else toast(err.message,true);}
  finally{if(submit)submit.disabled=false;}
});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-overlay'))closeModal();});
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'){studio.filtersOpen=false;document.body.classList.remove('filters-open');$('#filter-sidebar')?.classList.remove('mobile-open');closeModal();$('#search-panel').hidden=true;$('#mobile-nav').hidden=true;}
  if(e.key==='Tab'&&$('.modal')){const focusables=$$('a,button:not(:disabled),input,select,textarea', $('.modal'));const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}
});
window.addEventListener('popstate',()=>{closeModal();render();});
icons();
(async()=>{try{await Promise.all([syncUser(),refreshTaxonomy()]);await render();}catch(err){$('#main').innerHTML=`<section class="container page-space">${empty('Chưa kết nối được tủ đồ',err.message,'Thử lại','/','return')}</section>`;}})();
